/**
 * Shared workflow JSON import/export logic.
 *
 * Used by the workflow list (`workflow.vue`) and the v2 designer
 * (`workflow-designer-v2.vue`), which both let the user export a workflow as
 * JSON and (in the list) re-import one. The functions here handle the network
 * calls, filename resolution, file-type validation, and the browser download;
 * callers keep their own loading spinner and error handling (these throw on
 * failure).
 */
import { workflowApiService } from 'src/services';
import { allowed_file_type_json } from 'src/constants';

/**
 * The JSON envelope the workflow export endpoint returns, and the exact shape
 * the import endpoint expects to receive back. Mirrors the backend
 * `WorkflowExportData` model field for field.
 *
 * The whole envelope has to reach the downloaded file, not just `data`. The
 * import endpoint chooses between the standard and the advanced handler purely
 * on the top-level `version`, so a file that lost it is read as a standard
 * (v1) workflow; an advanced graph taken down that path then fails on a
 * missing `when_condition`. `name` carries the workflow name that the import
 * otherwise has to guess from the filename.
 */
export interface WorkflowJsonExport {
  /** Envelope format: 1 for standard workflows, 2 for advanced ones. */
  export_version: number;
  /** Workflow name, restored by the import. */
  name: string;
  /** Execution version: 1 standard, 2 if/else branching, 3 advanced graph. */
  version: number;
  /** Workflow payload: the cards for v1/v2, the node graph for v3. */
  data: Record<string, unknown>;
  /** Free-text description; carried in the file, not read by the import. */
  description?: string;
}

/**
 * Resolves the download filename from a `Content-Disposition` header,
 * preferring the RFC 5987 `filename*=UTF-8''…` form over the plain
 * `filename="…"` form, and falling back when the header is absent.
 *
 * Not used by `downloadWorkflowJson`: the shared API client resolves to the
 * response body alone, so no response headers survive to this module. Only a
 * caller holding a raw axios response can feed this.
 */
export function filenameFromContentDisposition(
  header: string | undefined,
  fallback: string,
): string {
  if (!header) return fallback;
  // Preferred: filename*=UTF-8''<percent-encoded-utf8>
  const ext = /filename\*=UTF-8''([^;]+)/i.exec(header);
  if (ext?.[1]) {
    try {
      return decodeURIComponent(ext[1]);
    } catch {
      /* fall through */
    }
  }
  // Quoted form first: everything up to the CLOSING quote belongs to the name.
  // A single `[^";]+` class would stop at a semicolon *inside* the quotes and
  // silently truncate names like "Meffert; Rechnungen.json" to "Meffert",
  // taking the .json tail with it (DOCB-12693).
  const quoted = /filename="([^"]+)"/i.exec(header);
  if (quoted?.[1]) return quoted[1];
  // Unquoted form: runs to the next parameter. `filename=` must match without
  // the RFC 5987 star so a failed filename*= decode above cannot fall through
  // and return the raw "*=UTF-8''…" parameter text as the name.
  const plain = /filename=([^";]+)/i.exec(header);
  return plain?.[1]?.trim() || fallback;
}

/**
 * Guarantees a `.json` extension on the exported filename.
 *
 * The name reaching the browser comes either from the server's
 * `Content-Disposition` or from the workflow's own name, and neither is
 * guaranteed to carry the extension. Without it the file is not recognised as
 * JSON and cannot be re-imported until the user renames it by hand
 * (DOCB-12693). A dot inside the name (e.g. a "v1.2" version suffix) is not an
 * extension, so only a literal `.json` tail is accepted.
 */
export function ensureJsonExtension(filename: string): string {
  return filename.toLowerCase().endsWith('.json') ? filename : `${filename}.json`;
}

/**
 * Fetches a workflow's JSON export and triggers a browser download.
 * Throws on failure so the caller can surface the error and stop its spinner.
 *
 * The service layer resolves to the parsed response body, so what arrives here
 * is the `WorkflowJsonExport` envelope itself: there is no axios wrapper to
 * unpack, and the server's `Content-Disposition` has already been dropped by
 * the time this runs. The file written to disk is therefore the entire
 * envelope, and the download name comes from the envelope's own `name`.
 */
export async function downloadWorkflowJson(
  workflowId: string,
  fallbackName: string,
): Promise<void> {
  const exported = (await workflowApiService.exportworkflowtojson(
    workflowId,
  )) as WorkflowJsonExport | Blob;

  // A Blob means the service was switched to responseType:'blob' and already
  // holds the encoded envelope; anything else is the parsed envelope, which is
  // serialized whole.
  const blob =
    exported instanceof Blob
      ? exported
      : new Blob([JSON.stringify(exported)], { type: 'application/json' });

  const exportedName = exported instanceof Blob ? '' : exported.name;
  const filename = ensureJsonExtension(exportedName || fallbackName);

  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = filename;
  link.click();
  URL.revokeObjectURL(link.href);
}

/**
 * Whether a file is an allowed workflow-JSON upload, checked first by MIME
 * type and then by file extension (some browsers report an empty type).
 */
export function hasAllowedFileType(file: {
  type: string;
  name: string;
}): boolean {
  if (allowed_file_type_json.includes(file.type)) {
    return true;
  }
  const lastDotIndex = file.name.lastIndexOf('.');
  const extension = file.name.substring(lastDotIndex + 1);
  return allowed_file_type_json.includes(extension);
}

/**
 * Uploads one or more workflow JSON files to be imported. Returns the raw
 * service response so the caller can inspect `success`/`message` and refresh
 * its list; throws on transport failure.
 */
export async function importWorkflowJson(formData: FormData): Promise<any> {
  return workflowApiService.importWorkflowJson(formData);
}
