<template class="col-12 q-pb-md workflow-height-limit">
  <q-card class="standard-popup-size">
    <q-card-section class="row background-color">
      <q-toolbar
        class="secondary-toolbar"
        style="margin-top: -10px; margin-bottom: -10px"
      >
        <q-toolbar-title>
          <span class="text-weight-bold text-white">{{
            $t('wf_workflow_templates_title')
          }}</span>
        </q-toolbar-title>

        <q-btn flat round dense icon="close" color="white" v-close-popup />
      </q-toolbar>
    </q-card-section>

    <q-card-section class="row">
      <q-input
        v-model="searchTemplateBy"
        dense
        :class="
          searchTemplateBy.length === 0
            ? 'search-in-active col-9'
            : 'search-active col-9'
        "
        autofocus
        :placeholder="$t('wf_search_template')"
        outlined
        @update:model-value="inputValueChangesTemplateSearch()"
        style="padding-right: 5px"
      >
        <template v-slot:append>
          <q-icon flat dense name="search" size="24px" color="primary" />
        </template>
      </q-input>
      <q-checkbox
        class="col-3"
        v-model="showDefaultTemplates"
        :label="$t('wf_show_default_templates')"
        :indeterminate-value="false"
        @update:model-value="loadTemplateDashboard"
      >
      </q-checkbox>
    </q-card-section>

    <q-card-section class="table-section-height">
      <DocBitsTable
        :rows="tableDataTemplate"
        :columns="templateColumns"
        row-key="id"
        table-id="wf_templates_table"
        :loading="loading"
        :features="{
          sorting: false,
          filtering: false,
          selection: false,
          bulkActions: false,
          rowActions: true,
          resizable: false,
          pagination: false,
          columnReorder: false,
          stickyLastColumn: true,
        }"
        :row-actions="templateRowActions"
        no-data-label="wf_no_templates_saved"
        flat-style
        @row-action="handleTemplateRowAction"
        @row-click="handleTemplateRowClick"
      >
        <template #body-cell-name="{ row }">
          <span
            style="font-size: 16px"
            :class="row.enabled == true ? 'enabled-name' : 'disabled-name'"
          >
            <q-badge v-if="row.org_id == 'default'" transparent align="middle" color="orange">
              {{ $t('wf_default_template') }}
            </q-badge>
            {{ row.name }}
          </span>
        </template>
        <template #body-cell-last_modified_by_name="{ row }">
          <template v-if="row.org_id == 'default'">-</template>
          <template v-else>{{ row.last_modified_by_name || '' }}</template>
        </template>
        <template #body-cell-last_modified_on="{ row }">
          <template v-if="row.org_id == 'default'">-</template>
          <template v-else-if="row.last_modified_on">{{ formatDateAccordingToPreference(row.last_modified_on) }}</template>
          <template v-else>{{ formatDateAccordingToPreference(row.created_on) }}</template>
        </template>
      </DocBitsTable>
      <div class="back-white flex justify-end">
        <q-pagination
          v-model="current_page_templates"
          color="primary"
          :max="total_pages_templates"
          class="q-py-xs q-mx-md"
          :max-pages="6"
          input
          boundary-links
          @update:model-value="nexPageClickedTemplates()"
        />
      </div>
    </q-card-section>
  </q-card>

  <q-dialog v-model="confirmDeleteTemplate" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('msg_delete') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn flat :label="$t('cancel')" color="primary" v-close-popup />
        <q-btn
          flat
          :label="$t('delete')"
          color="primary"
          v-close-popup
          @click="deleteTemplate()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { debounce } from 'quasar';
import { storeToRefs } from 'pinia';
import dateUtils from 'src/utils/date';
import { defineComponent, ref } from 'vue';
import helperUtil from 'src/utils/helperUtil';
import helperMixin from 'src/mixins/helperMixin';
import { workflowApiService } from 'src/services';
import { useDropdownStore } from 'src/store/main';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { RowActionItem, UnifiedTableColumn } from 'src/components/Table/types/table/unified-table';

export default defineComponent({
  name: 'workflowTemplates',
  mixins: [helperUtil, helperMixin, dateUtils],
  components: { DocBitsTable },
  data() {
    return {
      templateId: ref(''),
      confirmDeleteTemplate: ref(false),
      selectedRecordIndex: ref(),
      tableDataTemplate: {} as any,
      searchTemplateBy: ref(''),
      showDefaultTemplates: ref(true),
      templateColumns: [
        { name: 'name', label: this.$t('name'), field: 'name', align: 'left' },
        { name: 'last_modified_by_name', label: this.$t('last_saved_by'), field: 'last_modified_by_name', align: 'left' },
        { name: 'last_modified_on', label: this.$t('last_modified_on'), field: 'last_modified_on', align: 'left' },
      ] as UnifiedTableColumn[],
      templateRowActions: [
        { key: 'duplicate', label: 'duplicate', icon: 'content_copy' },
        { key: 'delete', label: 'delete', icon: 'delete', color: 'negative', separator: true, show: (row: any) => row.org_id !== 'default' },
      ] as RowActionItem[],
    };
  },

  mounted() {
    this.debounceSearchInputFuncTemplate = debounce(() => {
      this.loadTemplateDashboard();
    }, 1000);

    this.loadTemplateDashboard(); // has issues with showing normal dashboard
  },

  methods: {
    inputValueChangesTemplateSearch() {
      this.debounceSearchInputFuncTemplate();
    },
    async deleteTemplate() {
      let response: any;

      try {
        this.showLoading();
        response = await workflowApiService.deleteWorkflowTemplate(
          this.templateId,
        );
        if (!response.success) {
          throw response;
        }
        notify.success(this.$t('DELETED_SUCCESSFULLY'));
        this.tableDataTemplate.splice(this.selectedRecordIndex, 1);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    handleTemplateRowAction(payload: { action: string; row: any }) {
      if (payload.action === 'duplicate') {
        this.copyTemplate(payload.row.id);
      } else if (payload.action === 'delete') {
        const index = this.tableDataTemplate.indexOf(payload.row);
        this.templateId = payload.row.id;
        this.confirmDeleteTemplate = true;
        this.selectedRecordIndex = index;
      }
    },
    handleTemplateRowClick({ row }: { row: any }) {
      this.openTemplateDesigner(row.id);
    },
    async copyTemplate(templateId: string) {
      let response: any;

      try {
        this.showLoading();
        response = await workflowApiService.copyTemplate(templateId);
        if (!response.success) {
          throw response;
        }
        notify.success(this.$t('MSG_SAVE'));

        this.tableDataTemplate.splice(
          0,
          0,
          JSON.parse(JSON.stringify(response.workflow)),
        );
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async loadTemplateDashboard() {
      let response: any;
      try {
        this.loading = true;
        this.request_params_templates = {} as dynamicObj;
        this.request_params_templates['offset'] = this.offset_templates;
        this.request_params_templates['limit'] = this.page_size_templates;
        this.request_params_templates['order_by_direction'] = 'desc';
        this.request_params_templates['include_defaults'] =
          this.showDefaultTemplates;
        if (this.searchTemplateBy.length > 1) {
          this.request_params_templates['name'] = this.searchTemplateBy;
        }

        response = await workflowApiService.getTemplateDashboard(
          this.request_params_templates,
        );

        if (!response.success) {
          throw response;
        }

        if (
          response.all_entries_count > 0 &&
          response.entries.length == 0 &&
          this.showDefaultTemplates
        ) {
          this.resetPaginationTemplates();
          this.loadTemplateDashboard();
        }

        if (response.entries) {
          this.tableDataTemplate = response.entries;
        }
        this.total_records_templates = response.all_entries_count;
        this.setTotalPagesTemplates();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    openTemplateDesigner(templateId: string) {
      this.$router.push('/template_designer/' + templateId);
    },

    resetPaginationTemplates() {
      this.offset_templates = 0;
      this.total_pages_templates = 0;
      this.current_page_templates = 1;
      this.total_records_templates = 0;
    },

    setTotalPagesTemplates() {
      this.total_pages_templates = Math.ceil(
        this.total_records_templates / this.page_size_templates,
      );
    },

    async nexPageClickedTemplates() {
      try {
        this.calculateOffsetTemplates();
        await this.loadTemplateDashboard();
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    calculateOffsetTemplates() {
      this.offset_templates =
        this.page_size_templates * (this.current_page_templates - 1);
    },
  },
  setup() {
    const dropdown_store = useDropdownStore();
    const { doc_type_list, trigger_list, subOrgList } =
      storeToRefs(dropdown_store);

    const { getSubOrgsList, getDocumentTriggers } = dropdown_store;

    return {
      ShowTemplateDashboard: ref(true),
      loading: ref(false),
      formData: {} as FormData,
      debounceSearchInputFuncTemplate: {} as any,
      workflowTemplates: ref(false),
      request_params_templates: ref({} as dynamicObj),
      current_page_templates: ref(1),
      total_pages_templates: ref(1),
      offset_templates: ref(0),
      page_size_templates: ref(10),
      total_records_templates: ref(0),

      getSubOrgsList,
      getDocumentTriggers,
    };
  },
});
</script>

